"""A deliberately small, accessible chat UI over a bounded query API."""
import json
import streamlit as st
from ui import section_header,card
from analyst.demo import EXAMPLES,answer_demo


def _queue(question):
    st.session_state['analyst_pending']=question


def _clear():
    st.session_state['analyst_history']=[]
    st.session_state.pop('analyst_pending',None)


def render_result(answer):
    # All strings below are generated by our Python renderer, never executable HTML.
    st.write(answer['message'])
    for result in answer['results']:
        st.markdown('**'+result['title']+'**')
        for line in result['lines']:st.markdown('- '+line.replace('$',r'\$'))
        st.write(result['explanation'])
        st.caption(result['context']+' Dollar display: '+result['dollar_basis']+'.')
        st.caption(result['limitation'])
        with st.expander('Sources and exact calculations'):
            for source in result['sources']:
                st.markdown(f"**{source['season']} · {source['definition']}** · [Payroll source]({source['payroll_url']}) · [Official MLB results]({source['standings_url']})")
            if result.get('inflation_source_url'):
                st.markdown('[BLS March CPI source]('+result['inflation_source_url']+') · March 2026 purchasing power, not baseball salary inflation.')
            st.json({'query':result['query'],'results':result['rows']},expanded=False)


def render_analyst(panel,default_years):
    section_header('Your baseball business analyst','Ask about the spending. Understand the results.')
    # Public release: no credential reader, paid selector, or provider path.
    # Also discard stale private-mode state when an older local session reruns.
    if st.session_state.get('analyst_mode','Free demo')!='Free demo':
        _clear()
    st.session_state['analyst_mode']='Free demo'
    st.caption('FREE DEMO · Runs locally in Python · No API key · No paid AI')
    with card('analyst_intro'):
        st.write('Ask about team spending, results, or the payroll benchmark. This limited demo recognizes a small set of question patterns and calculates answers in Python. It is not a language model.')
        st.caption('Questions can name their own seasons. Otherwise the current season selection is used for single-season questions; broad demo trends use comparable AP years. This chat is separate from Explore Teams filters.')
    allow_mixed=st.checkbox('Allow mixed-source comparisons with 2022 in this chat',value=False,key='analyst_mixed',on_change=_clear,
        help='2022 uses The Baseball Cube, not AP. Permission comes only from this checkbox, never from the assistant or question text. Changing it clears this chat.')
    if allow_mixed:st.warning('2022 permission is on. Cross-year payroll differences may reflect different source accounting.')
    else:st.caption('2022 is available on its own. Comparing it with AP years requires explicit permission above.')
    with st.expander('Try a question',expanded=True):
        left,right=st.columns(2)
        for i,question in enumerate(EXAMPLES):
            with left if i%2==0 else right:
                st.button(question,key=f'analyst_example_{i}',on_click=_queue,args=(question,),width='stretch')
    st.button('Clear conversation',key='analyst_clear',on_click=_clear)
    history=st.session_state.setdefault('analyst_history',[])
    pending=st.session_state.pop('analyst_pending',None)
    if pending:
        if len(history)>=12:st.info('This conversation has reached twelve questions. Clear it to start again.')
        else:
            with st.spinner('Checking the verified numbers…'):
                answer=answer_demo(pending,panel,default_years,allow_mixed)
            history.append({'question':pending,'answer':answer})
    for turn in history:
        with st.chat_message('user',avatar=':material/person:'):st.write(turn['question'])
        with st.chat_message('assistant',avatar=':material/analytics:'):render_result(turn['answer'])
    question=st.chat_input('Ask about team payrolls, wins, or the payroll benchmark…',max_chars=1200,key='analyst_question')
    if question:
        _queue(question);st.rerun()
    st.caption('History stays in this browser’s Streamlit session and is bounded to twelve questions. See Methodology for source definitions and research limits.')
    if history:
        st.download_button('Download this conversation',json.dumps(history,indent=2,ensure_ascii=False).encode(),'business_of_winning_chat.json','application/json',key='analyst_download')
    with st.expander('What this analyst can and cannot do'):
        st.write('Supported: team payrolls and records, payroll-per-win rankings, comparisons, historical trends, annual payroll models, consistency, Colorado sensitivity, and sources. Unsupported: causes of team performance, management quality, player-level statistics, live news, betting advice, future predictions, revenue, or profit. The public release cannot call a paid model, execute code, or browse the web.')
        st.caption('Paid AI is unavailable in this public release, even if API credentials exist on the server. The experimental model integration remains mock-tested only and has no public entry point.')
